public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    java.util.Set<String> nodeSet = new java.util.HashSet<>();
    java.util.function.Function<int[], String> toKey = (int[] arr) -> {
        java.lang.StringBuilder sb = new java.lang.StringBuilder();
        sb.append('[');
        for (int i = 0; i < arr.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(arr[i]);
        }
        sb.append(']');
        return sb.toString();
    };
    java.util.function.Consumer<int[]> addNode = (int[] arr) -> {
        String key = toKey.apply(arr);
        if (!adj.containsKey(key)) {
            adj.put(key, new java.util.ArrayList<>());
        }
        nodeSet.add(key);
    };
    // add start and end nodes
    addNode.accept(start);
    addNode.accept(end);
    // process paths
    for (int[] pathArr : paths) {
        if (pathArr.length != 2 * n) continue; // skip invalid
        int[] nodeA = new int[n];
        int[] nodeB = new int[n];
        System.arraycopy(pathArr, 0, nodeA, 0, n);
        System.arraycopy(pathArr, n, nodeB, 0, n);
        String keyA = toKey.apply(nodeA);
        String keyB = toKey.apply(nodeB);
        adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }
    String startKey = toKey.apply(start);
    String endKey = toKey.apply(end);
    if (startKey.equals(endKey)) return "can be travelled";
    java.util.Deque<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors != null) {
            for (String nb : neighbors) {
                if (!visited.contains(nb)) {
                    if (nb.equals(endKey)) return "can be travelled";
                    visited.add(nb);
                    queue.add(nb);
                }
            }
        }
    }
    return "cannot be travelled";
}

